import { ExecutionContext, ForbiddenException } from '@nestjs/common';

import { OriginGuard } from '../src/origin.guard';

function buildContext(headers: Record<string, string>): ExecutionContext {
  const request = { headers };
  return {
    switchToHttp: () => ({ getRequest: () => request }),
  } as unknown as ExecutionContext;
}

function buildGuard(corsOrigins: string[]): OriginGuard {
  const configService = { getOrThrow: jest.fn().mockReturnValue({ corsOrigins }) };
  return new OriginGuard(configService as never);
}

describe('OriginGuard', () => {
  it('allows any request when CORS_ORIGIN is not configured', () => {
    const guard = buildGuard([]);
    const context = buildContext({});

    expect(guard.canActivate(context)).toBe(true);
  });

  it('allows a request whose Origin header matches a configured allowlist entry', () => {
    const guard = buildGuard(['https://app.example.com']);
    const context = buildContext({ origin: 'https://app.example.com' });

    expect(guard.canActivate(context)).toBe(true);
  });

  it('rejects a request whose Origin header does not match the allowlist', () => {
    const guard = buildGuard(['https://app.example.com']);
    const context = buildContext({ origin: 'https://evil.example.com' });

    expect(() => guard.canActivate(context)).toThrow(ForbiddenException);
  });

  it('rejects a request with no Origin header when an allowlist is configured', () => {
    const guard = buildGuard(['https://app.example.com']);
    const context = buildContext({});

    expect(() => guard.canActivate(context)).toThrow(ForbiddenException);
  });
});

