3	import {
4	  ACCOUNT_ROLE_REPOSITORY,
5	  AccountRoleRepository,
6	  CreateAccountUseCase,
7	  ROLE_REPOSITORY,
8	  RoleRepository,
9	  SeedRolesAndPermissionsUseCase,
10	} from '@memories/modules/identity-access';
11	import { AppConfig } from '@memories/platform/configuration';
12	import { TOKEN_SERVICE, TokenService } from '@memories/platform/security';
13	import { INestApplication } from '@nestjs/common';
14	import { ConfigService } from '@nestjs/config';
15	import { Test, TestingModule } from '@nestjs/testing';
16	import request from 'supertest';
17	
18	import { AppModule } from '../src/app.module';
19	import { configureApp } from '../src/configure-app';
20	
21	/**
22	 * Requires the local infrastructure stack (`docker compose -f docker/docker-compose.yml
23	 * --profile infrastructure up -d`) and a populated `.env`; run via `npm run test:e2e`.
24	 *
25	 * Exercises MEMORIES-0002's login/authorization/CRUD flows end to end against a real
26	 * Postgres-backed AppModule — the real HTTP layer, guards and use cases, not mocks. Test-only
27	 * setup (seeding roles/permissions, provisioning a bootstrap SUPER_ADMIN, granting extra roles)
28	 * goes through `CreateAccountUseCase`/`AccountRoleRepository` obtained directly from the Nest
29	 * container (`{ strict: false }`, same pattern as `media-upload-flow.e2e-spec.ts`) since there is
30	 * no HTTP-only way to create the very first admin account — every other assertion goes through
31	 * `supertest` against the real routes.
32	 */
33	const API_PREFIX = '/api/v1';
34	
35	interface Credentials {
36	  accountId: string;
37	  userProfileId: string;
38	  phone: string;
39	  password: string;
40	}
41	
42	describe('Auth & portal authorization flow (e2e)', () => {
43	  let app: INestApplication;
44	  let tokenService: TokenService;
45	  let createAccount: CreateAccountUseCase;
46	  let accountRoles: AccountRoleRepository;
47	  let roles: RoleRepository;
48	  let roleIdByCode: Map<string, string>;
49	
50	  beforeAll(async () => {
51	    const moduleRef: TestingModule = await Test.createTestingModule({
52	      imports: [AppModule],
53	    }).compile();
54	    app = moduleRef.createNestApplication();
55	    configureApp(app, moduleRef.get(ConfigService).getOrThrow<AppConfig>('app'));
56	    await app.init();
57	
58	    tokenService = moduleRef.get(TOKEN_SERVICE);
59	    createAccount = moduleRef.get(CreateAccountUseCase, { strict: false });
60	    accountRoles = moduleRef.get(ACCOUNT_ROLE_REPOSITORY, { strict: false });
61	    roles = moduleRef.get(ROLE_REPOSITORY, { strict: false });
62	
63	    const seed = moduleRef.get(SeedRolesAndPermissionsUseCase, { strict: false });
64	    await seed.execute();
65	
66	    roleIdByCode = new Map<string, string>();
67	    for (const code of ['PUBLIC_USER', 'ADMIN', 'SUPER_ADMIN']) {
68	      const role = await roles.findByCode(code);
69	      if (!role) {
70	        throw new Error(`Role ${code} was not seeded`);
71	      }
72	      roleIdByCode.set(code, role.id.toValue());
73	    }
74	  }, 30_000);
75	
76	  afterAll(async () => {
77	    await app.close();
78	  });
79	
80	  /** 09 + 8 random digits — confirmed a valid VN mobile shape via libphonenumber-js. Random
81	   * (not a per-run counter) so re-running this suite against a database that still has rows
82	   * from a previous run can't collide on the unique `provider + identifier` constraint. */
83	  function nextPhone(): string {
84	    const suffix = randomInt(10_000_000, 99_999_999);
85	    return `09${String(suffix).padStart(8, '0')}`;
86	  }
87	
88	  async function createTestAccount(extraRoleCode?: 'ADMIN' | 'SUPER_ADMIN'): Promise<Credentials> {
89	    const phone = nextPhone();
90	    const password = 'Sup3rSecret!';
91	    const output = await createAccount.execute({
92	      phone,
93	      password,
94	      fullName: 'E2E Test User',
95	    });
96	    if (extraRoleCode) {
97	      const roleId = roleIdByCode.get(extraRoleCode);
98	      if (!roleId) {
99	        throw new Error(`Role ${extraRoleCode} not resolved`);
100	      }
101	      await accountRoles.assign(output.accountId, roleId, null, new Date());
102	    }
103	    return { accountId: output.accountId, userProfileId: output.userProfileId, phone, password };
104	  }
105	
106	  function login(phone: string, password: string, portal: 'PUBLIC' | 'ADMIN') {
107	    return request(app.getHttpServer()).post(`${API_PREFIX}/auth/login`).send({ phone, password, portal });
108	  }
109	
110	  describe('login', () => {
111	    it('logs in a default account on the PUBLIC portal', async () => {
112	      const account = await createTestAccount();
113	      const res = await login(account.phone, account.password, 'PUBLIC').expect(200);
114	
115	      expect(res.body.accessToken).toEqual(expect.any(String));
116	      expect(res.body.portal).toBe('PUBLIC');
117	      expect(res.body.permissions).toContain('portal.public.access');
118	      expect(res.headers['set-cookie']?.[0]).toMatch(/HttpOnly/i);
119	
120	      const claims = await tokenService.verifyAccessToken(res.body.accessToken);
121	      expect(claims.subject).toBe(account.accountId);
122	      expect(claims.portal).toBe('PUBLIC');
123	    });
124	
125	    it('logs in an account granted the ADMIN role on the ADMIN portal', async () => {
126	      const account = await createTestAccount('ADMIN');
127	      const res = await login(account.phone, account.password, 'ADMIN').expect(200);
128	
129	      expect(res.body.portal).toBe('ADMIN');
130	      expect(res.body.permissions).toContain('portal.admin.access');
131	    });
132	
133	    it('rejects a PUBLIC-only account attempting to log into the ADMIN portal without creating a session', async () => {
134	      const account = await createTestAccount();
135	      await login(account.phone, account.password, 'ADMIN').expect(403);
136	
137	      // No refresh session/token was issued for the rejected portal — the account can still log
138	      // into the portal it does have access to right afterwards.
139	      await login(account.phone, account.password, 'PUBLIC').expect(200);
140	    });
141	
142	    it('returns the same generic error for an unknown phone and for a wrong password (no account enumeration)', async () => {
143	      const account = await createTestAccount();
144	      const unknownPhoneRes = await login(nextPhone(), account.password, 'PUBLIC').expect(401);
145	      const wrongPasswordRes = await login(account.phone, 'wrong-password', 'PUBLIC').expect(401);
146	
147	      expect(unknownPhoneRes.body.message).toBe(wrongPasswordRes.body.message);
148	    });
149	
150	    it('rejects login for an INACTIVE account', async () => {
151	      const account = await createTestAccount();
152	      await request(app.getHttpServer())
153	        .patch(`${API_PREFIX}/accounts/${account.accountId}/status`)
154	        .set('Authorization', await adminBearer())
155	        .send({ status: 'INACTIVE' })
156	        .expect(204);
157	
158	      await login(account.phone, account.password, 'PUBLIC').expect(403);
159	    });
160	
161	    it('rejects login for a LOCKED account', async () => {
162	      const account = await createTestAccount();
163	      await request(app.getHttpServer())
164	        .patch(`${API_PREFIX}/accounts/${account.accountId}/status`)
165	        .set('Authorization', await adminBearer())
166	        .send({ status: 'LOCKED' })
167	        .expect(204);
168	
169	      await login(account.phone, account.password, 'PUBLIC').expect(403);
170	    });
171	
172	    it('rejects login for a deleted (soft-deleted) account', async () => {
173	      const account = await createTestAccount();
174	      await request(app.getHttpServer())
175	        .delete(`${API_PREFIX}/accounts/${account.accountId}`)
176	        .set('Authorization', await adminBearer())
177	        .expect(204);
178	
179	      await login(account.phone, account.password, 'PUBLIC').expect(401);
180	    });
181	  });
182	
183	  describe('refresh & logout', () => {
184	    it('rotates the refresh session and keeps the same portal', async () => {
185	      const account = await createTestAccount();
186	      const loginRes = await login(account.phone, account.password, 'PUBLIC').expect(200);
187	      const cookie = loginRes.headers['set-cookie'] as unknown as string[];
188	
189	      const refreshRes = await request(app.getHttpServer())
190	        .post(`${API_PREFIX}/auth/refresh`)
191	        .set('Cookie', cookie)
192	        .expect(200);
193	
194	      expect(refreshRes.body.portal).toBe('PUBLIC');
195	      expect(refreshRes.body.sessionId).not.toBe(loginRes.body.sessionId);
196	
197	      const claims = await tokenService.verifyAccessToken(refreshRes.body.accessToken);
198	      expect(claims.subject).toBe(account.accountId);
199	    });
200	
201	    it('revokes the session once the account is locked, so a later refresh fails', async () => {
202	      const account = await createTestAccount();
203	      const loginRes = await login(account.phone, account.password, 'PUBLIC').expect(200);
204	      const cookie = loginRes.headers['set-cookie'] as unknown as string[];
205	
206	      await request(app.getHttpServer())
207	        .patch(`${API_PREFIX}/accounts/${account.accountId}/status`)
208	        .set('Authorization', await adminBearer())
209	        .send({ status: 'LOCKED' })
210	        .expect(204);
211	
212	      await request(app.getHttpServer()).post(`${API_PREFIX}/auth/refresh`).set('Cookie', cookie).expect(401);
213	    });
214	
215	    it('logout revokes the current session so the refresh cookie can no longer be used', async () => {
216	      const account = await createTestAccount();
217	      const loginRes = await login(account.phone, account.password, 'PUBLIC').expect(200);
218	      const cookie = loginRes.headers['set-cookie'] as unknown as string[];
219	
220	      await request(app.getHttpServer())
221	        .post(`${API_PREFIX}/auth/logout`)
222	        .set('Authorization', `Bearer ${loginRes.body.accessToken}`)
223	        .set('Cookie', cookie)
224	        .expect(204);
225	
226	      await request(app.getHttpServer()).post(`${API_PREFIX}/auth/refresh`).set('Cookie', cookie).expect(401);
