  const suffix = randomInt(10_000_000, 99_999_999);
  return `09${String(suffix).padStart(8, '0')}`;
}

/** Provisions a real Account (so `JwtAuthGuard`'s live status/tokenVersion check accepts the
 * token) and mints an access token for it directly via `TokenService`, bypassing the
 * phone/password login flow — this suite only needs a valid authenticated subject, not portal
 * authorization, which media routes don't check. */
