    }
  }

  it('runs create -> upload -> confirm -> worker through to `ready`', async () => {
    const ownerId = randomUUID();
    const authorization = await authHeader(ownerId);
    // confirm-upload cross-checks the real uploaded object's Content-Type/Content-Length against
    // what was declared at creation time — must match exactly for this flow to reach 'ready'.
    const fileBytes = Buffer.from('e2e-test-fixture-bytes');

    const createResponse = await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media`)
      .set('Authorization', authorization)
      .send({ mimeType: 'image/png', sizeBytes: fileBytes.byteLength })
      .expect(201);

    const { mediaAssetId, uploadUrl, objectKey } = createResponse.body as {
      mediaAssetId: string;
      uploadUrl: string;
      objectKey: string;
    };
    expect(objectKey).toMatch(/\.png$/);

    const uploadResponse = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: fileBytes,
    });
    expect(uploadResponse.ok).toBe(true);

    await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media/${mediaAssetId}/confirm-upload`)
      .set('Authorization', authorization)
      .expect(202);

    // The relay's automatic timer is disabled (see beforeAll) — publish the enqueued outbox row
    // explicitly instead of waiting on a natural tick.
    await outboxRelay.pollOnce();

    const settled = await pollUntilSettled(authorization, mediaAssetId);

    expect(settled.status).toBe('ready');
    expect(settled.processedObjectKey).toBe(`processed/${objectKey}`);
  }, 30_000);

  it('rejects a direct upload whose actual size does not match the size declared at creation time', async () => {
    // Regression test: the presigned PUT URL's signature now includes the declared sizeBytes as
    // an exact Content-Length requirement (see CreateMediaAssetUseCase/S3StorageAdapter) — real
    // S3/MinIO include content-length in the presigned PUT's signed-headers set, so a request
    // whose actual Content-Length differs fails signature verification (403) before any bytes are
    // stored. Without this, a client could declare a small size at creation time and then upload
    // an object of any size using the same presigned URL, leaving unbounded objects in storage.
    const ownerId = randomUUID();
    const authorization = await authHeader(ownerId);
    const declaredBytes = Buffer.from('small');

    const createResponse = await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media`)
      .set('Authorization', authorization)
      .send({ mimeType: 'image/png', sizeBytes: declaredBytes.byteLength })
      .expect(201);
    const { uploadUrl } = createResponse.body as { uploadUrl: string };

    const oversizedBytes = Buffer.alloc(declaredBytes.byteLength + 1024, 'x');
    const uploadResponse = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: oversizedBytes,
    });

    expect(uploadResponse.ok).toBe(false);
    expect(uploadResponse.status).toBe(403);
  });

  it('marks the asset failed (never ready) when the object is overwritten after confirm but before the worker processes it', async () => {
    // Regression test (TOCTOU): the presigned PUT URL used for the direct-to-S3 upload remains
    // usable until it expires — confirm-upload only proves what the object looked like AT THAT
    // MOMENT. Without comparing the worker's own re-read against the ETag captured at confirm
    // time, an object swapped out after confirmation (using the SAME still-valid presigned URL)
    // but before the worker actually runs would be silently processed as if it were the original,
    // already-validated file.
    const ownerId = randomUUID();
    const authorization = await authHeader(ownerId);
    const originalBytes = Buffer.from('e2e-toctou-original-bytes');

    const createResponse = await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media`)
      .set('Authorization', authorization)
      .send({ mimeType: 'image/png', sizeBytes: originalBytes.byteLength })
      .expect(201);
    const { mediaAssetId, uploadUrl, objectKey } = createResponse.body as {
      mediaAssetId: string;
      uploadUrl: string;
      objectKey: string;
    };

    const uploadResponse = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: originalBytes,
    });
    expect(uploadResponse.ok).toBe(true);

    await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media/${mediaAssetId}/confirm-upload`)
      .set('Authorization', authorization)
      .expect(202);

    // Overwrite the SAME key with different (but still declared-MIME-type/size-compatible)
    // bytes, using a fresh presigned URL for that key — modeling the still-valid original URL
    // being reused, or any other write access to the same key, after confirmation succeeded.
    // The relay's automatic timer is disabled (see beforeAll), so this deterministically happens
    // before the worker ever reads the object, not merely in a narrowed race window.
    const overwriteBytes = Buffer.from('e2e-toctou-SWAPPED-bytes!');
    const overwriteUrl = await storage.createPresignedUploadUrl({
      bucket: StorageBucket.PrivateOriginals,
      objectKey,
      contentType: 'image/png',
      contentLength: overwriteBytes.byteLength,
    });
    const overwriteResponse = await fetch(overwriteUrl.url, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: overwriteBytes,
    });
    expect(overwriteResponse.ok).toBe(true);

    await outboxRelay.pollOnce();

    const settled = await pollUntilSettled(authorization, mediaAssetId);
    expect(settled.status).toBe('failed');
    expect(settled.failureReason).toMatch(/no longer matches the version validated at confirm-upload time/);
    // Never processed: the swapped object must not have been promoted to `ready`, which would
    // mean the MIME/size validation at confirm time was silently bypassed.
    expect(settled.processedObjectKey).toBeFalsy();
  }, 30_000);

  it('marks the asset failed when the object goes missing, then reprocess brings it to ready once restored', async () => {
    const ownerId = randomUUID();
    const authorization = await authHeader(ownerId);
    const fileBytes = Buffer.from('e2e-reprocess-fixture-bytes');

    const createResponse = await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media`)
      .set('Authorization', authorization)
      .send({ mimeType: 'image/png', sizeBytes: fileBytes.byteLength })
      .expect(201);
    const { mediaAssetId, uploadUrl, objectKey } = createResponse.body as {
      mediaAssetId: string;
      uploadUrl: string;
      objectKey: string;
    };

    const uploadResponse = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: fileBytes,
    });
    expect(uploadResponse.ok).toBe(true);

    await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media/${mediaAssetId}/confirm-upload`)
      .set('Authorization', authorization)
      .expect(202);

    // Delete the object out from under the flow (real S3 delete via the same StoragePort the
    // app uses) BEFORE publishing the enqueued job — the relay's automatic timer is disabled
    // (see beforeAll), so the worker cannot possibly read the object until this explicit
    // pollOnce() call, which only happens after the delete above. This is fully deterministic,
    // not merely a narrowed race window.
    await storage.deleteObject('private-originals', objectKey);
    await outboxRelay.pollOnce();

    const failed = await pollUntilSettled(authorization, mediaAssetId);
    expect(failed.status).toBe('failed');
    expect(failed.failureReason).toBe('Source object no longer exists in storage');

    // Restore the object, then reprocess: this is the round-8 fix under test — reprocessing a
    // `failed` asset used to be impossible (GenerateThumbnailUseCase's CAS only accepted
    // processing -> ready), so this exact sequence would previously stay stuck `failed` forever.
    const restoreUrl = await storage.createPresignedUploadUrl({
      bucket: StorageBucket.PrivateOriginals,
      objectKey,
      contentType: 'image/png',
      contentLength: fileBytes.byteLength,
    });
    const restoreResponse = await fetch(restoreUrl.url, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: fileBytes,
    });
    expect(restoreResponse.ok).toBe(true);

    await reprocessMediaAsset.execute(mediaAssetId);
    await outboxRelay.pollOnce();

    const settled = await pollUntilSettled(authorization, mediaAssetId);
    expect(settled.status).toBe('ready');
    expect(settled.processedObjectKey).toBe(`processed/${objectKey}`);
    // The previous attempt's failure message must not leak through once the asset is genuinely
    // ready again — reprocess clears it atomically in the same CAS that starts the new attempt.
    expect(settled.failureReason).toBeUndefined();
  }, 30_000);

  it('reconciliation sweeping the OLD failed job never clobbers a newer reprocess attempt (attempt-scoped CAS)', async () => {
    const ownerId = randomUUID();
    const authorization = await authHeader(ownerId);
    const fileBytes = Buffer.from('e2e-reconcile-race-fixture-bytes');

    const createResponse = await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media`)
      .set('Authorization', authorization)
      .send({ mimeType: 'image/png', sizeBytes: fileBytes.byteLength })
      .expect(201);
    const { mediaAssetId, uploadUrl, objectKey } = createResponse.body as {
      mediaAssetId: string;
      uploadUrl: string;
      objectKey: string;
    };

    const uploadResponse = await fetch(uploadUrl, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: fileBytes,
    });
    expect(uploadResponse.ok).toBe(true);

    await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media/${mediaAssetId}/confirm-upload`)
      .set('Authorization', authorization)
      .expect(202);

    // First attempt fails (object missing) — BullMqWorkerRunner's own in-process
    // notifyFinalFailure already marks the asset `failed`, but the job itself stays in BullMQ's
    // Redis-backed failed set (removeOnFail retention), exactly as it would in production. The
    // relay's automatic timer is disabled (see beforeAll), so the worker cannot read the object
    // until this explicit pollOnce() call, which only happens after the delete above.
    await storage.deleteObject('private-originals', objectKey);
    await outboxRelay.pollOnce();
    const failed = await pollUntilSettled(authorization, mediaAssetId);
    expect(failed.status).toBe('failed');

    // Restore the object so the NEW attempt can actually succeed.
    const restoreUrl = await storage.createPresignedUploadUrl({
      bucket: StorageBucket.PrivateOriginals,
      objectKey,
      contentType: 'image/png',
      contentLength: fileBytes.byteLength,
    });
    const restoreResponse = await fetch(restoreUrl.url, {
      method: 'PUT',
      headers: { 'Content-Type': 'image/png' },
      body: fileBytes,
    });
    expect(restoreResponse.ok).toBe(true);

    // Reprocess: moves the asset back to `processing` under a brand-new, attempt-scoped job ID,
    // while the OLD failed job is still sitting untouched in Redis. Deliberately NOT publishing
    // this new attempt's outbox row yet (the relay's automatic timer is disabled, and pollOnce()
    // is only called further below) — this deterministically guarantees the new job cannot
    // possibly complete before the sweep/status check right after, instead of merely relying on
    // the old natural-timer window being unlikely to fire in time.
    await reprocessMediaAsset.execute(mediaAssetId);

    // Fire FailureReconciliationService's sweep for the OLD failed job right now — the
    // worst-case timing for the race this round's fix (currentJobId-scoped CAS) closes. Without
    // it, this would replay the OLD job's handleFinalFailure and incorrectly flip the asset from
    // the NEW attempt's `processing` back to `failed`, permanently stranding the new attempt.
    await failureReconciliation.sweepOnce();

    const afterSweep = await request(apiApp.getHttpServer())
      .get(`${API_PREFIX}/media/${mediaAssetId}`)
      .set('Authorization', authorization)
      .expect(200);
    expect(afterSweep.body.status).toBe('processing');

    // Only now publish the new attempt's job, so it can actually run and complete.
    await outboxRelay.pollOnce();

    const settled = await pollUntilSettled(authorization, mediaAssetId);
    expect(settled.status).toBe('ready');
    expect(settled.processedObjectKey).toBe(`processed/${objectKey}`);
  }, 30_000);

  it('rejects an unsupported MIME type at creation time, before any upload or job is involved', async () => {
    const ownerId = randomUUID();
    const authorization = await authHeader(ownerId);

    await request(apiApp.getHttpServer())
      .post(`${API_PREFIX}/media`)
      .set('Authorization', authorization)
      .send({ mimeType: 'application/pdf', sizeBytes: 1024 })
      .expect(400);
  });

  it("emitting 'error' on a real BullMQ Worker does not crash the process", () => {
    // Regression test: Node's EventEmitter throws (and can crash the process) if an 'error'
    // event is emitted with no listener registered. BullMQ's Worker emits 'error' for connection
    // issues and internal worker-loop failures — a separate channel from a job's own 'failed'
    // event — so this exercises a REAL BullMQ Worker instance (the exact ones apps/worker's
    // BullMqWorkerRunner already has running for this suite), not a mock.
    const workers = (workerRunner as unknown as { workers: Worker[] }).workers;
    expect(workers.length).toBeGreaterThan(0);

    expect(() => {
      workers[0]!.emit('error', new Error('simulated connection error'));
    }).not.toThrow();
  });
});

